// Logos with gradients or clip paths refer to their own ids. When one logo appears several times
// on a page (menu, cards, technology strip), repeated ids make the browser use the first copy's
// definitions — often inside a hidden menu — so the others draw blank. Each copy gets unique ids.
function withUniqueIds(body, uid) {
  return body
    .replace(/id="([^"]+)"/g, `id="$1-${uid}"`)
    .replace(/url\(#([^)]+)\)/g, `url(#$1-${uid})`)
    .replace(/href="#([^"]+)"/g, `href="#$1-${uid}"`)
}

export default function TechLogo({ name, className }) {
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, '')
  const logo = logos[name]
  return (
    <svg
      className={className}
      viewBox={logo.viewBox}
      aria-hidden="true"
      dangerouslySetInnerHTML={{ __html: withUniqueIds(logo.body, uid) }}
    />
  )
}
